  return SCHED.map(function(v){ return {name:v.name, ageMonths:v.age, due:addMonths(birthISO,v.age)}; }); }
function status(dueISO, todayISO){ todayISO=todayISO||new Date().toISOString().slice(0,10);
  var d=new Date(dueISO), t=new Date(todayISO); var diff=Math.round((d-t)/86400000);
  if(diff>30) return 'upcoming'; if(diff<-30) return 'overdue'; return 'due'; }
